<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';requireRole('dosen');$base='..';$assetBase='../assets';$pageTitle='Laporan Presensi';require __DIR__.'/../partials/head.php'; ?><div class="dashboard-layout"><?php require __DIR__.'/../partials/sidebar.php'; ?><main class="main"><div class="mobile-head"><b>Sistem Absensi QR</b><button class="menu-toggle">☰</button></div><header class="topbar"><div><h1>Laporan Presensi</h1><p>Ringkasan kehadiran berdasarkan sesi.</p></div><div class="top-actions"><a class="btn btn-ghost" href="../index.php">↗ Beranda</a></div></header>
<?php $did=(int)($pdo->query("SELECT d.id FROM dosen d JOIN users u ON u.username=d.nidn WHERE u.id=".userId())->fetchColumn()?:0);$st=$pdo->prepare("SELECT s.tanggal,mk.nama_mk,k.nama_kelas,COUNT(km.mahasiswa_id) total,COALESCE(SUM(a.status IN ('Hadir','Terlambat')),0) hadir,COALESCE(SUM(a.status='Tidak Hadir' OR a.id IS NULL),0) tidak_hadir FROM sesi_absensi s JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id JOIN kelas k ON k.id=j.kelas_id JOIN kelas_mahasiswa km ON km.kelas_id=k.id LEFT JOIN absensi a ON a.sesi_id=s.id AND a.mahasiswa_id=km.mahasiswa_id WHERE j.dosen_id=? GROUP BY s.id ORDER BY s.tanggal DESC");$st->execute([$did]);$rows=$st->fetchAll(); ?><section class="section"><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Mata Kuliah</th><th>Kelas</th><th>Total</th><th>Hadir</th><th>Tidak hadir</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><?=e($r['nama_mk'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=$r['total']?></td><td><?=$r['hadir']?></td><td><?=$r['tidak_hadir']?></td></tr><?php endforeach;?></tbody></table></div></section>
</main></div><?php require __DIR__.'/../partials/footer.php'; ?>